contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test drives c and asserts a simple observable property distinguishing P and M.
    // Parameters:
    // - depositor: address that will send ether to this test contract so it can fund c
    // - deployer: the address that was used as _owner when c was constructed (owner in C)
    // - attacker: an address that will attempt to call withdrawAll
    // - amount: amount of wei to forward into c

    receive() external payable {}

    function run(address payable depositor, address deployer, address attacker, uint256 amount) public payable {
        // Preconditions for meaningful test
        require(amount > 0);
        require(msg.sender == depositor, "caller must be depositor to fund test");
        // Fund this test contract so it can forward to c
        require(address(this).balance >= amount, "insufficient balance provided to test contract");

        // Send funds into c so withdrawAll has a balance to transfer
        payable(address(c)).transfer(amount);

        // Observe balances before withdraw
        uint256 beforeAttacker = address(attacker).balance;
        uint256 beforeC = address(c).balance;

        // Attempt withdrawal from attacker address by calling c.withdrawAll from this contract
        // To simulate attacker making the call, we require that this contract is the attacker
        // Caller will be this contract; tx.origin remains the original EOA (depositor)
        // We perform the state-changing call as specified.
        c.withdrawAll(payable(attacker));

        // Observe balances after withdraw
        uint256 afterAttacker = address(attacker).balance;
        uint256 afterC = address(c).balance;

        // On original contract P: only owner (constructor _owner) can call withdrawAll. Since this contract called it
        // and this contract is (in general) not equal to owner, the call should have reverted and no transfer should occur.
        // On mutant M: require(tx.origin == owner) would succeed if tx.origin equals owner (deployer), allowing transfer.
        // We assert the general rule: either c lost no funds OR the recipient gained exactly beforeC.
        // But to be distinguishing and machine-checkable we assert specifically that the contract's balance did not decrease
        // (i.e., the withdrawal did not happen when caller is not the stored owner). This holds on P for all inputs
        // where this contract is not the stored owner, and is violated by M when tx.origin == owner.

        assert(afterC == beforeC);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // Make the call from the provided caller by using a low-level call simulation:
        // We simulate an external caller by having this contract perform a CALL to C using delegatecall-like behavior is not allowed.
        // Instead, we use Solidity's call with explicit sender cannot be set; so to test different msg.sender we require the provided caller be this contract's address when used.
        // But since we cannot change msg.sender here, we instead assert that if the provided caller is not the recorded owner (accessible via c.owner()), then withdrawAll must revert when called by that caller. We observe behavior when this contract calls withdrawAll and relate it to the parameter: original contract enforces owner() == msg.sender so only owner can succeed.
        try c.withdrawAll(caller) { reverted = false; } catch { reverted = true; }
        // General rule: if the provided caller is not equal to c.owner(), then the call must have reverted.
        assert((caller != c.owner()) == reverted);
    }
    receive() external payable {}
}

