import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz: caller - address that will attempt the withdraw (may be owner or not)
    function testFuzz_property(address caller, address recipient, uint128 fund) public {
        // keep fund in a reasonable range
        fund = uint128(bound(fund, 0, 1 ether));
        // avoid zero address for recipient to keep semantics clear
        if (recipient == address(0)) recipient = address(1);

        // Fund the contract from an external account
        vm.deal(address(this), fund);
        // send funds into c so there's a balance to withdraw
        if (fund > 0) {
            // send from this contract to c
            (bool s, ) = address(c).call{value: fund}("");
            require(s);
        }

        // If the caller is the owner (address(this)), withdraw should succeed.
        // If caller is not owner, withdraw should revert (only owner may withdraw).
        // We perform the call as 'caller'. If caller equals owner, the call must succeed.
        // If caller != owner, the call must fail.

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(payable(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: the reference contract's rule — only the owner may successfully withdraw —
        // must hold for all inputs: ok == (caller == address(this)).
        assertTrue(ok == (caller == address(this)));
    }
}

