pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters:
    // - caller: an EOA that will attempt to call withdrawAll (fuzzer supplies)
    // - recipient: address to receive funds (fuzzer supplies)
    // We deploy an intermediate CallerContract which will call c.withdrawAll(recipient).
    // The general property: if an EOA calls withdrawAll directly (via vm.prank), only owner (address(this)) can withdraw.
    // To expose the mutant that checks tx.origin, we instead have the EOA call through a contract; the mutant may allow withdrawal when tx.origin==owner even though msg.sender!=owner.
    function testFuzz_property(address caller, address recipient) public {
        // Keep domain wide but avoid trivial zero-address recipient which still would work; allow zero to be valid too.
        // Ensure caller is not the owner (address(this)) to make the property meaningful: the correct contract should forbid withdrawal
        vm.assume(caller != address(this));

        // Fund the contract so withdrawAll would transfer something
        vm.deal(address(c), 1 ether);

        // Deploy a helper contract that will call c.withdrawAll(recipient)
        CallerContract helper = new CallerContract(c);

        // Give the helper some ether so it can forward calls if needed
        vm.deal(address(helper), 0);

        // 1) Direct call from caller (EOA) should NOT be allowed to withdraw because caller != owner
        //    We try/catch to observe whether the call succeeded (did not revert).
        bool okDirect;
        vm.deal(caller, 0);
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            okDirect = true;
        } catch {
            okDirect = false;
        }

        // After the direct call attempt, reset contract balance for the next scenario if it was drained.
        // If direct succeeded (unexpected for correct contract), top up again so the next scenario has funds.
        if (address(c).balance == 0) vm.deal(address(c), 1 ether);

        // 2) Indirect call: have the EOA caller externally call the helper contract, and the helper will in turn call c.withdrawAll(recipient).
        // This models a non-owner EOA calling through a contract; the correct contract should still forbid withdrawal because msg.sender (helper) != owner.
        bool okIndirect;
        vm.prank(caller);
        try helper.callWithdraw(recipient) {
            okIndirect = true;
        } catch {
            okIndirect = false;
        }

        // The universal property we assert: for any caller != owner, a direct EOA call must not succeed in withdrawing (okDirect == false).
        // This holds for the reference C for all inputs. The mutant (which checks tx.origin==owner) can be bypassed when owner is a contract or tx.origin equals owner;
        // by ensuring caller != owner and using a contract intermediary, the mutant may allow withdrawal on indirect calls while the correct contract forbids it.
        assertTrue(!okDirect);
    }
}

// Minimal helper that calls into C
contract CallerContract {
    C immutable c;
    constructor(C _c) {
        c = _c;
    }
    function callWithdraw(address recipient) external {
        c.withdrawAll(recipient);
    }
}

