pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: callerContractSalt lets fuzzer produce different attacker contract addresses;
    // recipient is where withdrawAll will send funds; callerIsOwner indicates whether the EOA origin should be the owner
    function testFuzz_property(uint256 callerContractSalt, address recipient, bool callerIsOwner) public {
        // Keep domain wide but avoid zero recipient which could be less informative
        if (recipient == address(0)) recipient = address(1);

        // Fund contract so there's something to withdraw
        vm.deal(address(c), 1 ether);

        // Deploy a minimal caller contract at a deterministic address using CREATE2 via a factory pattern
        // so fuzzer can vary callerContractSalt to get different caller contract addresses/contexts.
        AttackerFactory factory = new AttackerFactory();

        // Decide tx.origin: if callerIsOwner == true, make the EOA origin be the owner (address(this))
        // We simulate by having this test contract (owner) call into the factory to make it deploy and then call c.
        // If callerIsOwner == false, we use a different EOA by prank to deploy and call.

        address caller;
        if (callerIsOwner) {
            // deploy attacker contract from owner (address(this)) so tx.origin == owner
            caller = factory.deployCaller{value: 0}(address(c), recipient, callerContractSalt);
            // call withdrawAll through the caller contract using the owner as tx.origin
            // owner calls into the caller contract which then calls c.withdrawAll(recipient)
            // so tx.origin == owner, but msg.sender == caller (the contract)
            factory.callThrough(caller);
        } else {
            // Use a different EOA as tx.origin (an arbitrary address chosen by fuzzer indirectly via prank)
            address otherEOA = address(uint160(uint256(keccak256(abi.encodePacked(callerContractSalt, recipient)))));
            vm.deal(otherEOA, 1 ether);
            vm.prank(otherEOA);
            caller = factory.deployCaller(address(c), recipient, callerContractSalt);
            // Now have that otherEOA call through the deployed caller
            vm.prank(otherEOA);
            factory.callThrough(caller);
        }

        // After the call, in the correct contract C, only the owner (address(this)) could have caused a successful withdraw
        // If tx.origin was owner (callerIsOwner == true), the correct contract still requires msg.sender == owner, so a contract caller should NOT be able to withdraw.
        // We assert that the contract's balance is zero only when the call was legitimately made by the owner EOA itself (i.e., not via an intermediate contract).
        // The universal property we assert: calling withdrawAll via an intermediate contract (so msg.sender != owner) must NOT change C's balance (it must remain 1 ether).

        // Determine whether the call we performed was via a contract caller (it always is, since factory.deployCaller deploys a contract)
        // So we assert: address(c).balance == 1 ether (no withdrawal occurred) for all inputs where msg.sender != owner (which is our scenario)
        assertTrue(address(c).balance == 1 ether);
    }
}

// Minimal factory that can deploy a caller contract and invoke it; keeps logic simple and deterministic
contract AttackerFactory {
    function deployCaller(address target, address recipient, uint256 salt) external payable returns (address) {
        bytes memory creation = abi.encodePacked(type(Caller).creationCode, abi.encode(target, recipient));
        address addr;
        assembly {
            addr := create2(0, add(creation, 0x20), mload(creation), salt)
        }
        return addr;
    }
    function callThrough(address caller) external {
        Caller(caller).go();
    }
}

contract Caller {
    address public target;
    address public recipient;
    constructor(address _target, address _recipient) {
        target = _target;
        recipient = _recipient;
    }
    // invoke withdrawAll on target
    function go() external {
        C(target).withdrawAll(recipient);
    }
}

