contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: caller contract code choice (as boolean) and a recipient address
    function testFuzz_property(bool useMaliciousCaller, address recipient) public {
        // keep recipient wide but non-zero to avoid sending to zero-address edge-case
        vm.assume(recipient != address(0));

        // fund the contract so withdrawAll has something to transfer
        vm.deal(address(c), 1 ether);

        bool ok;
        if (!useMaliciousCaller) {
            // direct call from an EOA: only owner (this) should succeed
            vm.prank(address(this));
            try c.withdrawAll(recipient) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // call routed through a caller contract: its msg.sender will be that contract
            // but tx.origin will be the EOA we set with vm.prank. Deploy a simple forwarder
            Forwarder f = new Forwarder();
            // make sure forwarder has no funds needed
            // perform tx as address(this) so tx.origin == address(this)
            vm.prank(address(this));
            try f.forwardWithdraw(payable(address(c)), recipient) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The invariant: only the owner (address(this)) may successfully withdraw when calling withdrawAll.
        // On the correct contract, withdrawAll succeeds iff msg.sender == owner. In our test, when useMaliciousCaller
        // is false we call directly from owner (address(this)) so it must succeed (ok==true). When useMaliciousCaller is
        // true we call via a contract (Forwarder) so msg.sender != owner and the call must fail (ok==false) on the correct contract.
        // This single assert reads c only via its behavior (withdrawAll success/failure) and will hold for reference C
        // but the mutant (which checks tx.origin) can make the forwarded call succeed (tx.origin==owner) violating the rule
        if (!useMaliciousCaller) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}

contract Forwarder {
    // forwards a call to C.withdrawAll with msg.sender == this and tx.origin preserved
    function forwardWithdraw(address payable target, address recipient) external {
        // call the external contract's withdrawAll via low-level call to preserve semantics
        (bool s, ) = target.call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        require(s);
    }
}

