contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send some ether into this test contract so it can forward it to c if needed
    receive() external payable {}

    // Test that only the owner can trigger withdrawAll to move c's full balance to a chosen recipient
    // Parameters:
    // - senderIsOwner: if true, the caller of withdrawAll will be the owner address returned by c.owner();
    //                  if false, the caller will be some other address (provided as callerAddr).
    // - callerAddr: address used when senderIsOwner is false (must be non-zero and not equal to c.owner()).
    // - recipient: address to receive funds from c via withdrawAll.
    // - fundAmount: amount (wei) to ensure c has balance before withdrawAll is called.
    function testWithdrawAll(bool senderIsOwner, address callerAddr, address payable recipient, uint256 fundAmount) public payable {
        // Preconditions
        require(recipient != address(0));
        require(fundAmount > 0);
        // Ensure this contract has enough balance to fund c
        require(address(this).balance >= fundAmount);

        // Fund contract c by sending ether to its fallback
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // Record c balance before withdraw
        uint256 before = address(c).balance;
        require(before >= fundAmount);

        // Decide caller: if senderIsOwner, we will call withdrawAll from the observed owner address
        // We can only call from this contract, so enforce that the owner must equal address(this) when senderIsOwner==true
        // Otherwise ensure owner != address(this) and use normal call (which will be from this contract -> non-owner)
        address owner = c.owner();

        if (senderIsOwner) {
            // require that this contract is the owner so the call we make is from the owner
            require(owner == address(this));
            // As owner, call withdrawAll which should transfer the full balance to recipient
            c.withdrawAll(recipient);
        } else {
            // require that this contract is NOT the owner so the call we make is from a non-owner
            require(owner != address(this));
            // As non-owner, call withdrawAll which should revert on P, but succeed on mutant M.
            // We perform the call via low-level to capture success boolean without reverting this test contract.
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
            // Store result of non-owner attempt in a local via assert below
            // We use before and owner to express the expected relation: on P the non-owner call must fail and thus c.balance stays the same
            // On M the call will succeed and c.balance will become 0
            uint256 after = address(c).balance;
            // Assert that when a non-owner (this contract) calls withdrawAll, c's balance did not decrease
            // This asserts the security check exists: non-owners cannot drain c
            assert(after == before);
            // Also assert that the low-level call indicated failure (revert)
            assert(!ok);
            return;
        }

        // If we reached here, senderIsOwner was true and we called as owner. Now the contract should have transferred all funds to recipient.
        uint256 afterOwnerCall = address(c).balance;
        // The general rule: after a valid-owner withdrawAll call, c's balance becomes zero
        assert(afterOwnerCall == 0);
    }
}

